class Solution {
public:
    int minimumXORSum(vector<int>& nums1, vector<int>& nums2) {
        int n = nums1.size();
        vector<vector<long long>> cost(n, vector<long long>(n));
        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < n; ++j) {
                cost[i][j] = nums1[i] ^ nums2[j];
            }
        }

        vector<long long> u(n + 1), v(n + 1);
        vector<int> p(n + 1), way(n + 1);
        const long long INF = 1000000000000000000LL;

        for (int i = 1; i <= n; ++i) {
            p[0] = i;
            int j0 = 0;
            vector<long long> minv(n + 1, INF);
            vector<char> used(n + 1, false);
            do {
                used[j0] = true;
                int i0 = p[j0], j1 = 0;
                long long delta = INF;
                for (int j = 1; j <= n; ++j) {
                    if (!used[j]) {
                        long long cur = cost[i0 - 1][j - 1] - u[i0] - v[j];
                        if (cur < minv[j]) {
                            minv[j] = cur;
                            way[j] = j0;
                        }
                        if (minv[j] < delta) {
                            delta = minv[j];
                            j1 = j;
                        }
                    }
                }
                for (int j = 0; j <= n; ++j) {
                    if (used[j]) {
                        u[p[j]] += delta;
                        v[j] -= delta;
                    } else {
                        minv[j] -= delta;
                    }
                }
                j0 = j1;
            } while (p[j0] != 0);

            do {
                int j1 = way[j0];
                p[j0] = p[j1];
                j0 = j1;
            } while (j0);
        }

        long long ans = 0;
        for (int j = 1; j <= n; ++j) {
            if (p[j] != 0) {
                ans += cost[p[j] - 1][j - 1];
            }
        }
        return ans;
    }
};
